using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Net.Http;using System.Threading;using System.Threading.Tasks;using Ical.Net;using Ical.Net.CalendarComponents;using Ical.Net.DataTypes;using Ical.Net.Evaluation;
namespace CalendarWeather;
public sealed partial class Services {
 const int MaxCalendarBytes=5*1024*1024;
 internal static Uri SubscriptionUri(string value){if(!Uri.TryCreate(value.Trim(),UriKind.Absolute,out var uri))throw new InvalidOperationException("Informe um link de assinatura válido.");if(uri.Scheme=="webcal")uri=new UriBuilder(uri){Scheme="https",Port=-1}.Uri;if(uri.Scheme!="https"||!string.IsNullOrEmpty(uri.UserInfo))throw new InvalidOperationException("Use um link HTTPS ou webcal sem usuário e senha no endereço.");return uri;}
 public async Task<CalendarSnapshot> Subscription(Account account,CancellationToken ct){string content;if(account.Provider=="LocalIcs"){var file=new FileInfo(account.FeedUrl);if(file.Length>MaxCalendarBytes)throw new InvalidOperationException("Arquivo de calendário muito grande.");content=await File.ReadAllTextAsync(file.FullName,ct);}else{var uri=SubscriptionUri(account.FeedUrl);using var response=await http.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,ct);if(!response.IsSuccessStatusCode)throw new InvalidOperationException("Não foi possível ler a assinatura. Confira o link e o acesso ao calendário.");if(response.Content.Headers.ContentLength>MaxCalendarBytes)throw new InvalidOperationException("Calendário muito grande.");using var source=await response.Content.ReadAsStreamAsync(ct);using var memory=new MemoryStream();byte[] buffer=new byte[16384];int read;while((read=await source.ReadAsync(buffer,ct))>0){if(memory.Length+read>MaxCalendarBytes)throw new InvalidOperationException("Calendário muito grande.");await memory.WriteAsync(buffer.AsMemory(0,read),ct);}content=System.Text.Encoding.UTF8.GetString(memory.ToArray());}return await Task.Run(()=>ParseSubscription(content,account,DateTimeOffset.Now),ct);}
 internal static CalendarSnapshot ParseSubscription(string content,Account account,DateTimeOffset now){if(!content.Contains("BEGIN:VCALENDAR",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("O endereço não contém um calendário iCalendar/ICS.");var calendar=Ical.Net.Calendar.Load(content)??throw new InvalidOperationException("Calendário iCalendar inválido.");string id=account.Key+"|ics",name=string.IsNullOrWhiteSpace(account.SourceName)?account.Email:account.SourceName;var entries=new List<AgendaEvent>();var until=now.AddDays(14);int count=0;
 foreach(var occurrence in calendar.GetOccurrences<CalendarEvent>(new CalDateTime(now.AddDays(-1).UtcDateTime),new EvaluationOptions{MaxUnmatchedIncrementsLimit=10000})){var start=ToOffset(occurrence.Period.StartTime);if(start>=until)break;if(++count>5000)throw new InvalidOperationException("O calendário excede o limite de ocorrências no período.");if(occurrence.Source is not CalendarEvent item||!item.IsActive)continue;bool all=!occurrence.Period.StartTime.HasTime;var end=occurrence.Period.EffectiveEndTime is CalDateTime finish?ToOffset(finish):start.Add(all?TimeSpan.FromDays(1):TimeSpan.FromMinutes(1));if(end<=start)end=start.AddMinutes(1);if(end<=now)continue;string url=item.Url?.ToString()??"";if(!Uri.TryCreate(url,UriKind.Absolute,out var eventUri)||eventUri.Scheme!="https")url="";entries.Add(new((item.Uid??"event")+"|"+start.ToUniversalTime().ToString("O"),id,name,"#8BB9FF",item.Summary??"(Sem título)",start,end,all,url));}
 return new(Store.Upcoming(entries,now),new List<CalendarInfo>{new(id,name,"#8BB9FF")},DateTimeOffset.Now);}
 static DateTimeOffset ToOffset(CalDateTime value){if(value.IsFloating||!value.HasTime){var local=DateTime.SpecifyKind(value.Value,DateTimeKind.Unspecified);return new DateTimeOffset(local,TimeZoneInfo.Local.GetUtcOffset(local));}return new DateTimeOffset(value.AsUtc);}
}
